1036	Before proving the lemma we give definitions regarding distributions over lines and points.
1037	
1038	\begin{definition}\label{def:ith-restricted-line}
1118	\begin{proof}[Proof of \Cref{lem:qld-4-13}]
1119	We construct the measurements $\hat{Q}^\line_f$
1120	out of the lines measurements $T^{\line_X, \line_Z}_{f_X, f_Z}$
1121	guaranteed by \Cref{lem:qld-xz-lines}. To do so we first show how
1122	to map any line-point pair $(\line, u)$ in the expanded space
1123	$\F_q^{2m+2}$ to two pairs  $(\line_X, u_X)$ and  $(\line_Z, u_Z)$ in $\F_q^m$. We will 
1124	define $\hat{Q}^\line$ in terms of $T^{\line_X, \line_Z}_{f_X, f_Z}$ and
1125	show that the resulting measurement is consistent with the combined
1126	points measurement $\hat{Q}^{x,z,\alpha, \beta}$ from \Cref{lem:qld-4-12}.
1127	
1128	To define $\hat{Q}^\line$ we make use of the distribution $D$ from \Cref{lem:qld-sublines}. Let $D_{|\line}$ denote the distribution derived from $D$ by conditioning on the first element being $\line$. Then for every line $\line$ in $\F_q^{2m+2}$ and function $f \in \deg_{(md+1)}(\line)$, define
1129	\[ \hat{Q}^\line_f = \E_{(\line_X, \line_Z) \sim D_{|\line}} \sum_{\substack{f_X \in \deg_{md}(\line_X), f_Z \in \deg_{md}(\line_Z):\\ f = \combine_{f_X, f_Z}}} T^{\line_X, \line_Z}_{f_X, f_Z}\;, \]
1130	where $\combine_{f_X, f_Z}$ is defined in~\eqref{eq:combine-lines}. Note that $\{\hat{Q}^\line_f\}$ forms a valid POVM for every choice of line $\line$, and moreover that $\combine_{f_X, f_Z}$ is well-defined for the lines $\line, \line_X, \line_Z$ because of Property 2 of \Cref{lem:qld-sublines}. 
1131	
1132	Observe that by Property~3 of \Cref{lem:qld-sublines}, whenever $\line$ is axis-parallel, $\line_X$ and $\line_Z$ are axis-parallel also. Thus, in this case, by \Cref{lem:qld-xz-lines} it holds that the outcomes $f_X$ and $f_Z$ both have degree $d$. By definition of $\combine_{f_X, f_Z}$ it holds that the outcome $f$ of $\{\hat{Q}^\line_f\}$ has degree $d$ as well.
1133	
1134	We argue the following bound:
1135	\begin{align}
1136	  \E_{(\line, \line_X, \line_Z) \sim D} \E_{(x,z,\alpha, \beta) \in \line} &\sum_{f_X, f_Z} \bra{\hat{\psi}} T^{\line_X, \line_Z}_{f_X, f_Z} \ot (I - \hat{Q}^{x, z }_{f_X(x),f_Z(z)}) \ket{\hat{\psi}}  \,=\, O\big( m \cdot (\eps^{1/4} + \delta_P^{1/4} + \delta_Q^{1/4} + \delta_{\Line}^{1/2})\big)\;. \label{eq:qld-combined-lines-consistency}
1137	\end{align}
1138	This bound will follow from chaining the following three claims. 
1139	
1140	\begin{claim}\label{claim:17-1}
1141	\begin{align}
1142	  \E_{(\line, \line_X, \line_Z) \sim D} \E_{(x,z,\alpha, \beta) \in \line} &\sum_{f_X, f_Z} \bra{\hat{\psi}} T^{\line_X, \line_Z}_{f_X, f_Z} \ot \hat{Q}^{x, z }_{f_X(x),f_Z(z)} \ket{\hat{\psi}}  \notag\\
1143	       &\approx_{\delta_Q^{1/2}} \E_{(\line, \line_X, \line_Z) \sim D}  \E_{(x,z,\alpha, \beta) \in \line}  \sum_{f_X, f_Z} \bra{\hat{\psi}} T^{\line_X, \line_Z}_{f_X, f_Z} \ot \hat{M}^{(\Point,Z),z}_{f_Z(z)} \hat{M}^{(\Point,X),x}_{f_X(x)}  \ket{\hat{\psi}}\;. 
1144	\end{align}
1145	\end{claim}
1146	
1147	\begin{proof}
1148	Form the difference and apply the Cauchy Schwarz inequality to obtain
1149	\begin{align*}
1150	&\Big|  \E_{(\line, \line_X, \line_Z) \sim D} \E_{(x,z,\alpha, \beta) \in \line} \sum_{f_X, f_Z}\bra{\hat{\psi}} T^{\line_X, \line_Z}_{f_X, f_Z} \ot \big(\hat{Q}^{x, z }_{f_X(x),f_Z(z)}-\hat{M}^{(\Point,Z),z}_{f_Z(z)}\hat{M}^{(\Point,X),x}_{f_X(x)} \big) \ket{\hat{\psi}}\Big|\\
1151	&\leq \Big( \E_{(\line, \line_X, \line_Z) \sim D} \E_{(x,z,\alpha, \beta) \in \line} \sum_{f_X, f_Z} \big\|\sqrt{T^{\line_X, \line_Z}_{f_X, f_Z} }\ot \Id \ket{\hat{\psi}} \big\|^2 \Big)^{1/2}\\
1152	&\qquad\cdot \Big( \E_{(\line, \line_X, \line_Z) \sim D} \E_{(x,z,\alpha, \beta) \in \line} \sum_{f_X, f_Z}\big\| \sqrt{T^{\line_X, \line_Z}_{f_X, f_Z}} \ot \big(\hat{Q}^{x, z }_{f_X(x),f_Z(z)}-\hat{M}^{(\Point,Z),z}_{f_Z(z)}\hat{M}^{(\Point,X),x}_{f_X(x)} \big) \ket{\hat{\psi}}\big\|^2 \Big)^{1/2}\;.
1153	\end{align*}
1154	The first term above is at most $1$. For the second term, writing 
1155	\[W^{x,z}_{a,b} = \big(\hat{Q}^{x, z }_{a,b}- \hat{M}^{(\Point,Z),z}_{b}\hat{M}^{(\Point,X),x}_{a}\big)\]
1156	for short
1157	we bound it as 
1158	\begin{align*}
1159	\E_{(\line, \line_X, \line_Z) \sim D} \E_{(x,z,\alpha, \beta) \in \line}  \sum_{f_X, f_Z}\big\| \sqrt{T^{\line_X, \line_Z}_{f_X, f_Z}} \ot W^{x,z}_{f_X(x),f_Z(z)} \ket{\hat{\psi}}\big\|^2 
1160	&\leq \E_{(\line, \line_X, \line_Z) \sim D} \E_{(x,z,\alpha, \beta) \in \line} \sum_{a,b}\bra{\hat{\psi}} \Id \ot (W^{x,z}_{a,b})^2 \ket{\hat{\psi}} \\
1161	&= \E_{(x,z)} \sum_{a,b}\bra{\hat{\psi}} \Id \ot (W^{x,z}_{a,b})^2 \ket{\hat{\psi}} \\
1162	&\leq \delta_Q\;.
1163	\end{align*}
1164	Here the first inequality uses that for any $x,z,a,b$, $\sum_{f_X,f_X: f_X(x)=a,f_Z(z)=b} T^{\line_X, \line_Z}_{f_X, f_Z}\leq \Id$. 
1165	In the equality in the before-last line, the expectation is over independent uniform $x,z\in \F_q^m$. The equality holds because for a line $\ell$ sampled from the line-point distribution $D$, a uniformly random point $(x,z,\alpha,\beta)$ on $\ell$ is distributed as a uniformly random point in $\F_q^{2m+2}$. The last inequality is by~\eqref{eq:qld-q-cons-m-hat-zx}.
1166	\end{proof}
1167	
1168	\begin{claim}\label{claim:17-2}
1169	\begin{align}
1170	  \E_{(\line, \line_X, \line_Z) \sim D} \E_{(x,z,\alpha, \beta) \in \line} &\sum_{f_X, f_Z} \bra{\hat{\psi}} T^{\line_X, \line_Z}_{f_X, f_Z} \ot \hat{M}^{(\Point,Z),z}_{f_Z(z)}  \hat{M}^{(\Point,X),x}_{f_X(x)} \ket{\hat{\psi}}  \notag\\
1171	       &\approx_{m\delta_\Line^{1/2}} \E_{(\line, \line_X, \line_Z) \sim D}  \E_{(x,z,\alpha, \beta) \in \line} \sum_{f_X,f_Z} \bra{\hat{\psi}} T^{\line_X, \line_Z}_{f_X, f_Z} \ot  \hat{M}^{(\Point,Z),Z}_{f_Z(z)} \ket{\hat{\psi}}\;. 
1172	\end{align}
1173	\end{claim}
