1175	\begin{proof}
1176	We form the difference and apply the Cauchy-Schwarz inequality
1177	\begin{align*}
1178	 \Big|\E_{(\line, \line_X, \line_Z) \sim D} \E_{(x,z,\alpha, \beta) \in \line} &\sum_{f_X, f_Z} \bra{\hat{\psi}} T^{\line_X, \line_Z}_{f_X, f_Z} \ot \hat{M}^{(\Point,Z),z}_{f_Z(z)} (\Id-\hat{M}^{(\Point,X),x}_{f_X(x)} ) \ket{\hat{\psi}}\Big|\\
1179	&\leq \Big(\E_{(\line, \line_X, \line_Z) \sim D} \E_{(x,z,\alpha, \beta) \in \line} \sum_{f_X, f_Z} \big\| \sqrt{ T^{\line_X, \line_Z}_{f_X, f_Z}} \ot  \hat{M}^{(\Point,Z),z}_{f_Z(z)} \ket{\hat{\psi}}\big\|^2 \Big)^{1/2}\\
1180	&\qquad\cdot \Big(\E_{(\line, \line_X, \line_Z) \sim D} \E_{(x,z,\alpha, \beta) \in \line} \sum_{f_X, f_Z} \big\| \sqrt{ T^{\line_X, \line_Z}_{f_X, f_Z}} \ot  (\Id-\hat{M}^{(\Point,X),x}_{f_X(x)}) \ket{\hat{\psi}}\big\|^2 \Big)^{1/2}\;.
1181	\end{align*}
1182	The first term above is at most $1$. The second term can be bounded as
1183	\begin{align}
1184	\E_{(\line, \line_X, \line_Z) \sim D} \E_{(x,z,\alpha, \beta) \in \line} &\sum_{f_X, f_Z} \big\| \sqrt{ T^{\line_X, \line_Z}_{f_X, f_Z}} \ot  (\Id-\hat{M}^{(\Point,X),x}_{f_X(x)}) \ket{\hat{\psi}}\big\|^2 \notag\\
1185	&= \E_{(\line, \line_X, \line_Z) \sim D} \E_{(x,z,\alpha, \beta) \in \line} \sum_{a} \bra{\hat{\psi}}  T^{\line_X, \line_Z,x}_{a} \ot  (\Id-\hat{M}^{(\Point,X),x}_{a})^2 \ket{\hat{\psi}}\notag\\
1186	&= 1-\E_{(\line, \line_X, \line_Z) \sim D} \E_{(x,z,\alpha, \beta) \in \line} \sum_{a} \bra{\hat{\psi}}  T^{\line_X, \line_Z,x}_{a} \ot \hat{M}^{(\Point,X),x}_{a} \ket{\hat{\psi}}\;,\label{eq:17-4}
1187	\end{align}
1188	where we used the shorthand $T^{\line_X, \line_Z,x}_{a} = \sum_{f_X,f_Z: f_X(x)=a} T^{\line_X, \line_Z}_{f_X, f_Z}$ and the second equality uses that $\{\hat{M}^{(\Point,X),x}_{a}\}$ is a projective measurement. Using the definition 
1189	\[	T^{\line_\xpt,\line_\zpt}_{f_\xpt,f_\zpt} = \hat{M}^{(\Line,\xpt),\line_\xpt}_{f_\xpt} \cdot \hat{M}^{(\Line,\zpt),\line_\zpt}_{f_\zpt}  \cdot \hat{M}^{(\Line,\xpt),\line_\xpt}_{f_\xpt} \]
1190	and the fact that $\{\hat{M}^{(\Line,\xpt),\line_\xpt}_{f_\xpt} \}$ is projective we get
1191	\begin{align}
1192	1-\eqref{eq:17-4}&=\E_{(\line, \line_X, \line_Z) \sim D} \E_{(x,z,\alpha, \beta) \in \line} \sum_{a} \bra{\hat{\psi}}  \hat{M}^{(\Line,\xpt),\line_\xpt}_{[\eval_x(\cdot)=a]} \ot \hat{M}^{(\Point,X),x}_{a} \ket{\hat{\psi}}\;.\label{eq:a17-8}
1193	\end{align}
1194	By Property~2 of \Cref{lem:qld-sublines} the right-hand side of~\eqref{eq:a17-8}
1195	 is a mixture of terms of the form
1196	\begin{equation}\label{eq:a17-9}
1197	 \E_{(\line_X, x) \sim D_{\tvar, i}}  \sum_{a} \bra{\hat{\psi}}  \hat{M}^{(\Line,\xpt),\line_\xpt}_{[\eval_x(\cdot)=a]} \ot \hat{M}^{(\Point,X),x}_{a} \ket{\hat{\psi}}\;, 
1198	\end{equation}
1199	for $\tvar \in \{\ALine, \DLine\}$ and $i \in \{1, \dots, m\}$. 
1200	Hence by the discussion following Definition~\ref{def:ith-restricted-line} and  item 3 of Lemma~\ref{lem:qld-comm-line-cons} it follows that
1201	\[ \eqref{eq:a17-9} \,=\, O(m^2 \delta_\Line)\;. \]
1202	\end{proof}
