1204	\begin{claim}\label{claim:17-3}
1205	\begin{align}
1206	  \E_{(\line, \line_X, \line_Z) \sim D}\E_{(x,z,\alpha, \beta) \in \line}\sum_{f_X,f_Z} \bra{\hat{\psi}} T^{\line_X, \line_Z}_{f_X, f_Z} \ot  \hat{M}^{(\Point,Z),z}_{f_Z(z)} \ket{\hat{\psi}} 
1207	       &\approx_{\sqrt{m}\cdot(\delta_P^{1/4}+\delta_Q^{1/4}+\eps^{1/4})}1 \;. 
1208	\end{align}
